/**
 * derived_graph.js — Derived group tree CRUD data model
 *
 * Pure logic module. Zero DOM dependencies.
 * Part of Phase 1 datamodel layer for Issue #85.
 *
 * Data shape per node:
 *   { id, name, parentId, baseGroupId, isAutoGenerated, autoMode,
 *     productMask, feeOverride, closeTodayOverride, rebalanceOverride,
 *     metadata }
 *
 * Dependencies:
 *   - GT.datamodel.base_groups (for baseGroupId validation)
 *   - GT.state.emit (for derivedGraphChanged events)
 */

(function() {
    var GT = window.GroupTest;
    if (!GT) throw new Error('GroupTest bootstrap not loaded');
    if (!GT.datamodel) { GT.datamodel = {}; }

    // ---------------------------------------------------------------------------
    // Internal state
    // ---------------------------------------------------------------------------

    var _nodes = [];          // flat array of all derived group nodes
    var _idCounter = 0;

    var VALID_AUTO_MODES = [null, 'union', 'intersect'];

    // ---------------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------------

    function _uuid() {
        _idCounter += 1;
        return 'dg_' + Date.now().toString(36) + '_' + _idCounter.toString(36);
    }

    function _deepCopy(obj) {
        return JSON.parse(JSON.stringify(obj));
    }

    function _findIndex(id) {
        for (var i = 0; i < _nodes.length; i++) {
            if (_nodes[i].id === id) return i;
        }
        return -1;
    }

    /**
     * Check if `targetId` is an ancestor of `nodeId`.
     * Used for cycle detection when reparenting.
     */
    function _isAncestor(nodeId, targetId) {
        var node = get(nodeId);
        while (node) {
            if (node.parentId === targetId) return true;
            if (!node.parentId) return false;
            node = get(node.parentId);
        }
        return false;
    }

    /**
     * Check if `newParentId` would create a cycle if applied to `nodeId`.
     * A cycle occurs when `newParentId` === nodeId, or nodeId is an
     * ancestor of newParentId.
     */
    function _wouldCycle(nodeId, newParentId) {
        return (nodeId === newParentId) || _isAncestor(newParentId, nodeId);
    }

    /**
     * Recursively collect all descendant IDs of a node (inclusive).
     * Returns flat array of IDs.
     */
    function _collectDescendantIds(id) {
        var result = [id];
        for (var i = 0; i < _nodes.length; i++) {
            if (_nodes[i].parentId === id) {
                result = result.concat(_collectDescendantIds(_nodes[i].id));
            }
        }
        return result;
    }

    /**
     * Build a tree node (with children) for a given id.
     * Returns null if id not found.
     */
    function _buildTreeNode(id) {
        var idx = _findIndex(id);
        if (idx === -1) return null;

        var node = _deepCopy(_nodes[idx]);
        node.children = [];

        // Find direct children, sorted by insertion order (array order)
        for (var i = 0; i < _nodes.length; i++) {
            if (_nodes[i].parentId === id) {
                var childTree = _buildTreeNode(_nodes[i].id);
                if (childTree) node.children.push(childTree);
            }
        }

        return node;
    }

    // ---------------------------------------------------------------------------
    // Validation
    // ---------------------------------------------------------------------------

    /**
     * Validate a derived group config (before add or during update).
     * @param {object} config - raw config to validate
     * @param {string} [excludeId] - node id to exclude from uniqueness checks (for updates)
     * @returns {{valid: boolean, errors: string[]}}
     */
    function validate(config, excludeId) {
        var errors = [];

        if (!config || typeof config !== 'object') {
            return { valid: false, errors: ['config must be an object'] };
        }

        // Required: name
        if (!config.name || typeof config.name !== 'string' || !config.name.trim()) {
            errors.push('name is required (non-empty string)');
        }

        // Required: baseGroupId (BATCH_SENTINEL allowed for organisational batch nodes)
        var BATCH_SENTINEL = '__batch__';
        if (!config.baseGroupId || typeof config.baseGroupId !== 'string') {
            errors.push('baseGroupId is required (non-empty string)');
        } else if (config.baseGroupId !== BATCH_SENTINEL && GT.datamodel.base_groups && GT.datamodel.base_groups.get) {
            // Validate that the referenced base group exists (skip for batch sentinels)
            var bg = GT.datamodel.base_groups.get(config.baseGroupId);
            if (!bg) {
                errors.push('baseGroupId references a non-existent base group: ' + config.baseGroupId);
            }
        }

        // parentId: if provided, must be an existing node (and not a cycle — checked in add/update)
        if (config.parentId !== undefined && config.parentId !== null) {
            var parentIdx = _findIndex(config.parentId);
            if (parentIdx === -1) {
                errors.push('parentId references a non-existent derived group: ' + config.parentId);
            }
        }

        // autoMode: if provided, must be valid
        if (config.autoMode !== undefined && VALID_AUTO_MODES.indexOf(config.autoMode) === -1) {
            errors.push('autoMode must be one of: null, "union", "intersect"');
        }

        // isAutoGenerated must be boolean if provided
        if (config.isAutoGenerated !== undefined && typeof config.isAutoGenerated !== 'boolean') {
            errors.push('isAutoGenerated must be a boolean');
        }

        // Metadata must be object if provided
        if (config.metadata !== undefined && (typeof config.metadata !== 'object' || config.metadata === null)) {
            errors.push('metadata must be an object or null');
        }

        return { valid: errors.length === 0, errors: errors };
    }

    // ---------------------------------------------------------------------------
    // Public API
    // ---------------------------------------------------------------------------

    /**
     * Add a new derived group node.
     *
     * @param {object} config
     * @param {string} config.name
     * @param {string} config.baseGroupId   - must reference an existing base group
     * @param {string} [config.parentId]     - null for root; must be an existing node
     * @param {string} [config.autoMode]     - null, "union", or "intersect"
     * @param {boolean} [config.isAutoGenerated] - default false
     * @param {object} [config.productMask]   - default {}
     * @param {*}      [config.feeOverride]   - default null
     * @param {*}      [config.closeTodayOverride] - default null
     * @param {*}      [config.rebalanceOverride]  - default null
     * @param {object} [config.metadata]      - default {}
     * @returns {object} the created node (deep copy)
     * @throws {Error} if validation fails
     */
    function add(config) {
        var result = validate(config);
        if (!result.valid) {
            throw new Error('Validation failed: ' + result.errors.join('; '));
        }

        // Cycle detection: if parentId is specified and non-null,
        // the new node cannot be an ancestor of parentId
        if (config.parentId) {
            // For a new node, checking _wouldCycle would always pass
            // since the new node isn't in the tree yet. But validate
            // already checked parent exists.
        }

        var node = {
            id: _uuid(),
            name: config.name.trim(),
            parentId: config.parentId || null,
            baseGroupId: config.baseGroupId,
            isAutoGenerated: config.isAutoGenerated !== undefined ? !!config.isAutoGenerated : false,
            autoMode: config.autoMode !== undefined ? config.autoMode : null,
            productMask: config.productMask !== undefined ? _deepCopy(config.productMask) : {},
            feeOverride: config.feeOverride !== undefined ? config.feeOverride : null,
            closeTodayOverride: config.closeTodayOverride !== undefined ? config.closeTodayOverride : null,
            rebalanceOverride: config.rebalanceOverride !== undefined ? config.rebalanceOverride : null,
            metadata: config.metadata !== undefined ? _deepCopy(config.metadata) : {},
        };

        _nodes.push(node);
        _emit('derivedGraphChanged', { action: 'add', id: node.id });
        return _deepCopy(node);
    }

    /**
     * Get a deep copy of a derived group node by id.
     * @param {string} id
     * @returns {object|null}
     */
    function get(id) {
        var idx = _findIndex(id);
        if (idx === -1) return null;
        return _deepCopy(_nodes[idx]);
    }

    /**
     * Get deep copies of all derived group nodes (flat list).
     * @returns {object[]}
     */
    function getAll() {
        return _deepCopy(_nodes);
    }

    /**
     * Get the tree structure starting from root nodes.
     * Each node includes a `children` array of nested sub-trees.
     * @returns {object[]}
     */
    function getTree() {
        var roots = [];
        for (var i = 0; i < _nodes.length; i++) {
            if (!_nodes[i].parentId) {
                roots.push(_buildTreeNode(_nodes[i].id));
            }
        }
        return roots;
    }

    /**
     * Get all descendant IDs of a node (including itself).
     * @param {string} id
     * @returns {string[]}
     * @throws {Error} if node not found
     */
    function getDescendants(id) {
        if (_findIndex(id) === -1) throw new Error('Derived group not found: ' + id);
        return _collectDescendantIds(id);
    }

    /**
     * Partially update a derived group node.
     *
     * Special handling:
     * - Updating parentId: cycle detection (cannot reparent to self or descendant)
     * - Updating baseGroupId: validates reference exists
     *
     * @param {string} id
     * @param {object} patch
     * @returns {object} updated node (deep copy)
     * @throws {Error} if not found, validation fails, or cycle detected
     */
    function update(id, patch) {
        var idx = _findIndex(id);
        if (idx === -1) throw new Error('Derived group not found: ' + id);

        // Cycle detection for parentId change
        if ('parentId' in patch && patch.parentId !== null && patch.parentId !== _nodes[idx].parentId) {
            // Validate new parent exists
            var newParentIdx = _findIndex(patch.parentId);
            if (newParentIdx === -1) {
                throw new Error('New parentId references a non-existent derived group: ' + patch.parentId);
            }
            // Detect cycle
            if (_wouldCycle(id, patch.parentId)) {
                throw new Error('Cannot reparent: would create a cycle (node ' + id + ' is an ancestor of ' + patch.parentId + ')');
            }
        }

        // Validate the merged result
        var merged = _deepCopy(_nodes[idx]);
        Object.keys(patch).forEach(function(key) {
            merged[key] = patch[key];
        });
        var result = validate(merged, id);
        if (!result.valid) {
            throw new Error('Validation failed: ' + result.errors.join('; '));
        }

        // Apply patch
        Object.keys(patch).forEach(function(key) {
            if (key === 'productMask' || key === 'metadata') {
                _nodes[idx][key] = _deepCopy(patch[key]);
            } else {
                _nodes[idx][key] = patch[key];
            }
        });

        _emit('derivedGraphChanged', { action: 'update', id: id });
        return _deepCopy(_nodes[idx]);
    }

    /**
     * Remove a derived group node and ALL its descendants (cascade).
     *
     * @param {string} id
     * @returns {object} the removed root node (deep copy, with children tree)
     * @throws {Error} if not found
     */
    function remove(id) {
        var idx = _findIndex(id);
        if (idx === -1) throw new Error('Derived group not found: ' + id);

        // Build tree snapshot for return value
        var removedTree = _buildTreeNode(id);

        // Collect all descendant IDs and remove them
        var idsToRemove = _collectDescendantIds(id);

        _nodes = _nodes.filter(function(node) {
            return idsToRemove.indexOf(node.id) === -1;
        });

        _emit('derivedGraphChanged', { action: 'remove', id: id, removedIds: idsToRemove });
        return removedTree;
    }

    /**
     * Get a shallow summary list for dropdowns, tree UIs, etc.
     * @returns {{id: string, name: string, parentId: string|null, baseGroupId: string}[]}
     */
    function list() {
        return _nodes.map(function(node) {
            return {
                id: node.id,
                name: node.name,
                parentId: node.parentId,
                baseGroupId: node.baseGroupId,
            };
        });
    }

    /**
     * Reset all internal state (useful for testing).
     */
    function _reset() {
        _nodes = [];
        _idCounter = 0;
    }

    // ---------------------------------------------------------------------------
    // Event emission
    // ---------------------------------------------------------------------------

    function _emit(event, data) {
        if (GT.state && typeof GT.state.emit === 'function') {
            GT.state.emit(event, data);
        }
    }

    // ---------------------------------------------------------------------------
    // Export
    // ---------------------------------------------------------------------------

    GT.datamodel.derived_graph = {
        add: add,
        get: get,
        getAll: getAll,
        getTree: getTree,
        getDescendants: getDescendants,
        update: update,
        remove: remove,
        list: list,
        validate: validate,
        _reset: _reset,
    };

    GT.log('datamodel.derived_graph loaded');
})();